import 'package:flutter/material.dart';import '../../core/database/app_database.dart';import '../../data/repositories/quran_repository.dart';import '../../data/repositories/hifz_repository.dart';import '../../domain/hifz/hifz_engine.dart';import '../../data/models/ayah.dart';
class HifzSessionPage extends StatefulWidget{const HifzSessionPage({super.key});@override State<HifzSessionPage> createState()=>_HifzSessionPageState();}
class _HifzSessionPageState extends State<HifzSessionPage>{late Future<HifzPlan> plan;final repo=HifzRepository(AppDatabase.instance);bool hidden=false;@override void initState(){super.initState();plan=HifzEngine(QuranRepository(AppDatabase.instance),repo).today();}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Today’s Hifz')),body:FutureBuilder<HifzPlan>(future:plan,builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());final p=s.data!;return ListView(padding:const EdgeInsets.all(20),children:[_section(c,'🔄 Revision','Strengthen what you already learned',p.revision),const SizedBox(height:24),_section(c,'🌱 New memorization','Today’s next ayahs',p.newAyahs),const SizedBox(height:24),FilledButton.icon(onPressed:()=>setState(()=>hidden=!hidden),icon:Icon(hidden?Icons.visibility:Icons.visibility_off),label:Text(hidden?'Show ayahs':'Hide ayahs')),]);}));}Widget _section(BuildContext c,String title,String sub,List<Ayah> a)=>Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(title,style:Theme.of(c).textTheme.headlineSmall?.copyWith(fontWeight:FontWeight.w700)),const SizedBox(height:4),Text(sub),const SizedBox(height:12),if(a.isEmpty)const Card(child:Padding(padding:EdgeInsets.all(18),child:Text('Nothing due here yet. Keep going.'))) else ...a.map((x)=>Card(margin:const EdgeInsets.only(bottom:10),child:Padding(padding:const EdgeInsets.all(16),child:Column(children:[Text('Ayah ${x.surahId}:${x.ayahNumber}',style:Theme.of(c).textTheme.labelLarge),const SizedBox(height:8),Text(hidden?'••••••••••••••••••':x.textUthmani,textAlign:TextAlign.right,textDirection:TextDirection.rtl,style:const TextStyle(fontSize:26,height:1.8)),Row(mainAxisAlignment:MainAxisAlignment.end,children:[TextButton(onPressed:()=>repo.record(x.id,false),child:const Text('Needs work')),FilledButton(onPressed:()=>repo.record(x.id,true),child:const Text('I remembered'))])]))));}));}
